export const VARIABLE_LIMIT=1000000;
export const defaultScenarioVariables=()=>Array.from({length:4},(_,i)=>({name:`Variable ${i+1}`,initial:0}));
export function validateScenarioVariables(v){if(v===undefined)return defaultScenarioVariables();if(!Array.isArray(v)||v.length!==4)throw Error('Define four scenario variable slots.');const names=new Set();return Array.from(v,item=>{if(!item||typeof item.name!=='string'||!item.name.trim()||item.name.length>40||/[\x00-\x1f]/.test(item.name)||!Number.isInteger(item.initial)||Math.abs(item.initial)>VARIABLE_LIMIT||names.has(item.name.trim().toLowerCase()))throw Error('Variable names must be distinct, up to 40 characters; initial values must be whole numbers from −1,000,000 to 1,000,000.');names.add(item.name.trim().toLowerCase());return{name:item.name.trim(),initial:item.initial};});}
export function validateVariableValues(v){if(!Array.isArray(v)||v.length!==4||!Array.from(v).every(n=>Number.isInteger(n)&&Math.abs(n)<=VARIABLE_LIMIT))throw Error('Invalid saved scenario variable values.');return [...v];}
export function changeScenarioVariable(c,event,copyValue=0,read=()=>NaN,index=0){const before=c.scenario.variables[event.variable],calculated=event.operation==='calculate'?calculate(c,event,read,index):null;if(calculated?.error)return{ok:false,variableBefore:before,variableAfter:before,calculationError:calculated.error};const raw=calculated?calculated.raw:event.operation==='copy'?copyValue:event.operation==='add'?before+event.value:event.value,value=Math.max(-VARIABLE_LIMIT,Math.min(VARIABLE_LIMIT,Math.round(raw)));c.scenario.variables[event.variable]=value;return{variableBefore:before,variableAfter:value};}
export const CALCULATIONS={sum:'Add two values',subtract:'Subtract right from left',multiply:'Multiply',divide:'Divide left by right',percentage:'Left as percentage of right',random:'Random integer between values'};
export const CALCULATION_ERRORS={zeroDivisor:'Division by zero; variable unchanged.',nonFinite:'A metric was unavailable; variable unchanged.'};
export function validateCalculation(e,metrics){if(!Object.hasOwn(CALCULATIONS,e.calculation))throw Error('Choose a calculation.');const operand=v=>{if(v?.kind==='constant'&&Number.isInteger(v.value)&&Math.abs(v.value)<=VARIABLE_LIMIT)return{kind:'constant',value:v.value};if(v?.kind==='metric'&&Object.hasOwn(metrics,v.metric))return{kind:'metric',metric:v.metric};throw Error('Operands need a valid metric or whole number from −1,000,000 to 1,000,000.');};return{calculation:e.calculation,left:operand(e.left),right:operand(e.right)};}
export function calculationLabel(e,metrics){const label=o=>o.kind==='constant'?o.value.toLocaleString('en-US'):metrics[o.metric].name;return`${CALCULATIONS[e.calculation]}: ${label(e.left)}; ${label(e.right)}`;}
function calculate(c,event,read,index){const value=o=>o.kind==='constant'?o.value:read(o.metric),left=value(event.left),right=value(event.right);if(!Number.isFinite(left)||!Number.isFinite(right))return{error:'nonFinite'};if(['divide','percentage'].includes(event.calculation)&&right===0)return{error:'zeroDivisor'};let raw;switch(event.calculation){case'sum':raw=left+right;break;case'subtract':raw=left-right;break;case'multiply':raw=left*right;break;case'divide':raw=left/right;break;case'percentage':raw=left/right*100;break;case'random':{let seed=(c.seed^Math.imul(c.month+1,83492791)^Math.imul(index+1,19349663)^Math.imul(event.variable+1,73856093))>>>0;seed=Math.imul(seed^(seed>>>16),0x7feb352d);seed=Math.imul(seed^(seed>>>15),0x846ca68b);const unit=((seed^(seed>>>16))>>>0)/4294967296,lo=Math.round(Math.min(left,right)),hi=Math.round(Math.max(left,right));raw=lo+Math.floor(unit*(hi-lo+1));break;}default:throw Error('Unknown calculation.');}return Number.isFinite(raw)?{raw}:{error:'nonFinite'};}
